ALTER TABLE "organization_verification_requests" DROP CONSTRAINT "organization_requests_submission_check";--> statement-breakpoint
ALTER TABLE "organization_verification_requests" DROP CONSTRAINT "organization_requests_decision_check";--> statement-breakpoint
ALTER TABLE "organization_verification_requests" ADD CONSTRAINT "organization_requests_submission_check" CHECK (("organization_verification_requests"."status" = 'DRAFT' AND "organization_verification_requests"."submitted_at" IS NULL AND "organization_verification_requests"."snapshot_bytes" IS NULL AND "organization_verification_requests"."snapshot_hash" IS NULL) OR ("organization_verification_requests"."status" <> 'DRAFT' AND "organization_verification_requests"."submitted_at" IS NOT NULL AND "organization_verification_requests"."snapshot_bytes" IS NOT NULL AND "organization_verification_requests"."snapshot_hash" IS NOT NULL AND "organization_verification_requests"."snapshot_hash" ~ '^0x[0-9a-f]{64}$'));--> statement-breakpoint
ALTER TABLE "organization_verification_requests" ADD CONSTRAINT "organization_requests_decision_check" CHECK (("organization_verification_requests"."status" IN ('APPROVED','CHANGES_REQUESTED','REJECTED') AND "organization_verification_requests"."reviewed_at" IS NOT NULL AND "organization_verification_requests"."reviewed_by" IS NOT NULL AND "organization_verification_requests"."review_note" IS NOT NULL AND length("organization_verification_requests"."review_note") > 0) OR ("organization_verification_requests"."status" NOT IN ('APPROVED','CHANGES_REQUESTED','REJECTED') AND "organization_verification_requests"."reviewed_at" IS NULL AND "organization_verification_requests"."reviewed_by" IS NULL AND "organization_verification_requests"."review_note" IS NULL));